const input = $json;
const payload = input.payload ?? input.body ?? input;
const changeValue = payload?.entry?.[0]?.changes?.[0]?.value ?? {};
const message = changeValue?.messages?.[0] ?? null;
const contact = changeValue?.contacts?.[0] ?? null;
const metadata = changeValue?.metadata ?? {};
const blockers = [];
if (input.signature_valid !== true) blockers.push('SIGNATURE_NOT_VERIFIED');
if (!message?.id) blockers.push('EXTERNAL_MESSAGE_ID_MISSING');
if (!message?.from) blockers.push('SENDER_ID_MISSING');
if (!metadata?.phone_number_id) blockers.push('PHONE_NUMBER_ID_MISSING');

const textBody = message?.type === 'text' ? (message?.text?.body ?? '') : '';
const externalMessageId = message?.id ?? null;
const senderId = message?.from ?? contact?.wa_id ?? null;
const phoneNumberId = metadata?.phone_number_id ?? null;
const idempotencyKey = phoneNumberId && externalMessageId ? 'meta:' + phoneNumberId + ':' + externalMessageId : null;
const correlationId = input.correlation_id ?? externalMessageId ?? null;

const messageContext = {
  contract_version: '1.0.0',
  correlation_id: correlationId,
  channel: 'whatsapp',
  transport: 'meta_whatsapp',
  external_message_id: externalMessageId,
  idempotency_key: idempotencyKey,
  sender_id: senderId,
  sender_display_name: contact?.profile?.name ?? null,
  phone_number_id: phoneNumberId,
  display_phone_number: metadata?.display_phone_number ?? null,
  message_type: message?.type ?? null,
  text: textBody,
  occurred_at_unix: message?.timestamp ?? null,
  raw_payload_ref: 'fixture:inline'
};

return {
  json: {
    accepted: blockers.length === 0,
    duplicate: Boolean(input.duplicate),
    message_context: messageContext,
    canonical_event: blockers.length === 0 && !input.duplicate ? {
      event_type: 'message_received',
      event_version: '1.0.0',
      direction: 'inbound',
      source: 'meta_whatsapp',
      correlation_id: correlationId,
      idempotency_key: idempotencyKey,
      payload: { message_context: messageContext }
    } : null,
    requested_actions: blockers.length === 0 && !input.duplicate ? [{ action: 'RECORD_EVENT' }] : [],
    blockers
  }
};
